                                                                                                                                                                                                          
  CREATE TABLE "CODE_KNOWLEDGE"                                                                                                                                                                
   (	"KNOWLEDGE_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 2 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                               
	"CREATION_DATE" DATE,                                                                                                                                                                                    
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                               
	"UPDATED_DATE" DATE,                                                                                                                                                                                     
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                      
	"REMARK" NVARCHAR2(255),                                                                                                                                                                                 
	"IS_ENABLE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                       
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                        
	"KNOWLEDGE_NAME" NVARCHAR2(255),                                                                                                                                                                         
	"SORT_NUM" NUMBER(20,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                       
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                            
	 PRIMARY KEY ("KNOWLEDGE_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                     
   ) ;                                                                                                                                                                                                    

